def build():
    tasks = [dict(zip(('id','title','description','owner','date','priority','status','dependencies','acceptance','hours'), row)) for row in ROWS]
    for t in tasks:
        t['id'] = 'BT-' + t['id']
        t['owner'] = 'Participant ' + str(t['owner'])
        t['date'] = '2026-' + t['date']
        t['dependencies'] = ['BT-' + d for d in t['dependencies']]
    by_id = {t['id']: t for t in tasks}
    assert len(by_id) == len(tasks) >= 25
    visited, visiting = set(), set()
    def visit(key):
        assert key not in visiting, f'Cycle at {key}'
        if key in visited:
            return
        visiting.add(key)
        t = by_id[key]
        assert t['status'] in STATUSES and t['owner'] in ('Participant 1', 'Participant 2')
        assert t['priority'] in ('P0', 'P1', 'P2') and t['hours'] >= 0
        date.fromisoformat(t['date'])
        for dep in t['dependencies']:
            assert dep in by_id and by_id[dep]['date'] <= t['date']
            if t['status'] == 'Done':
                assert by_id[dep]['status'] == 'Done'
            visit(dep)
        visiting.remove(key)
        visited.add(key)
    for key in by_id:
        visit(key)
    ROOT.mkdir(parents=True, exist_ok=True)
    (ROOT / 'issues').mkdir(exist_ok=True)
    def write(name, text):
        (ROOT / name).write_text(text.rstrip() + '\n', encoding='utf-8')
    write('WBS.json', json.dumps(tasks, ensure_ascii=False, indent=2))
    header = '''# WBS — Bloody Trail, ЛР №10

Срез: 2026-10-28. План продолжения: 2026-10-29–2026-12-23.
Источник задач: `tools/build_lab10.py` от корня игры; генератор проверяет ID, даты, зависимости и циклы.
Ответственный — роль владельца проверки/дальнейшей поддержки, **не утверждение об авторстве существующего кода**.
Для Done дата — дата проверки наличия результата, а не выдуманный исторический срок выполнения.
Для остальных дата — плановая дата завершения. Часы — оставшаяся работа, уже выполненный труд не оценивался.
P0 — необходимо для приёмки; P1 — следующая очередь внутри согласованного scope; P2 — необязательное улучшение.
Backlog означает ещё не взято в работу; To Do — готово к началу; Testing — существующий результат ожидает ручной приёмки.
Все сроки и оценки являются предложенной базовой линией, а не подтверждённой доступностью студентов.

| ID | Название | Описание | Ответственный | Плановая дата | Приоритет | Статус | Зависимости | Критерий завершения | Осталось, ч |
|---|---|---|---|---|---|---|---|---|---|
'''
    lines = []
    for t in tasks:
        deps = ', '.join(t['dependencies']) or '—'
        lines.append('| ' + ' | '.join(str(v) for v in (t['id'],t['title'],t['description'],t['owner'],t['date'],t['priority'],t['status'],deps,t['acceptance'],t['hours'])) + ' |')
        write('issues/' + t['id'] + '.md', f'''# [{t['id']}] {t['title']}

{t['description']}

- Ответственный по плану: {t['owner']} (GitHub login назначается после принятия приглашения).
- Плановая дата: {t['date']}.
- Приоритет: {t['priority']}.
- Локальный статус на 2026-10-28: {t['status']}.
- Зависимости: {deps}.
- Оставшаяся оценка: {t['hours']} ч.

## Критерий завершения

- [{'x' if t['status'] == 'Done' else ' '}] {t['acceptance']}

## Свидетельства и проверка

Для Done основание — Baseline_Audit.md и локальные артефакты. Это не подтверждение персонального вклада.
Для новой работы добавить реальные commit/PR, версию сборки, команды проверки и фактический результат.
Тело подготовлено локально; номер Issue и URL ещё не присвоены.
''')
    totals = Counter()
    for t in tasks:
        totals[t['owner']] += t['hours']
    write('WBS.md', header + '\n'.join(lines) + '\n\nОставшаяся оценка: ' + '; '.join(f'{k} — {v} ч' for k,v in sorted(totals.items())) + f'; всего {sum(totals.values())} ч. Резерв расписания учитывается отдельно в Project_Plan.md.\n')
    board = '''# Kanban — Bloody Trail

Срез 2026-10-28. Локальная доска; GitHub Project не создан.

**Backlog → To Do → In Progress → Testing → Done**

Карточки ниже покрывают все WBS-ID ровно один раз. Подробности, сроки и зависимости — [WBS](WBS.md).
Подготовленные тела Issues находятся в [issues](issues/); порядок переноса — [GitHub Setup](GitHub_Setup.md).

'''
    for status in STATUSES:
        items = [t for t in tasks if t['status'] == status]
        board += f'## {status} ({len(items)})\n\n'
        board += '\n'.join(f"- [{t['id']} — {t['title']}](issues/{t['id']}.md) · {t['owner']} · {t['date']} · {t['priority']}" for t in items) if items else 'Нет задач: активная разработка новых функций на момент среза не подтверждена.'
        board += '\n\n'
    board += '''## Правила движения

- Backlog → To Do: согласованы критерий, входные данные и доступы; незавершённая зависимость блокирует начало зависимой реализации.
- To Do → In Progress: участник действительно начал работу и создал свою ветку. Лимит — одна активная задача на участника.
- In Progress → Testing: приложены изменения и проверка разработчика. Лимит Testing — две задачи одновременно.
- Testing → Done: второй участник проверил критерий, записал результат и реальные ссылки. Для исходного среза Done означает только наличие проверенного артефакта.
- При дефекте карточка возвращается в In Progress с описанием воспроизведения; риск отмечается в Risk Register.
- Блокировка — отдельная отметка Blocked с причиной и датой, без шестой колонки. Еженедельно пересматриваются сроки и риски.
- Сначала менять ROWS в `tools/build_lab10.py`, затем пересобирать представления. После импорта в GitHub выбрать одну основную доску и явно датировать локальные снимки, чтобы они не расходились.
'''
    write('Kanban.md', board)
    print(json.dumps({'tasks':len(tasks),'statuses':dict(Counter(t['status'] for t in tasks)), 'remaining_hours':dict(totals),'dependencies':'valid DAG'}, ensure_ascii=False))


if __name__ == '__main__':
    build()
